INSERT INTO `produits` (`id_produit`, `nom_produit`, `description_produit`, `prix_produit`, `produit_image`) VALUES
(20, 'Créer un site web - Le guide complet pour débutants: HTML, CSS, PHP, MySQL, Javascript', 'Créer un site web peut sembler intimidant quand on part de zéro. Trop de termes techniques, trop d’outils différents, trop de vidéos qui vont trop vite… Pourtant, avec un bon guide, clair et structuré, il est tout à fait possible de créer un site web même en étant débutant complet.\r\n\r\nCe livre a été conçu spécialement pour ceux qui souhaitent apprendre à créer un site internet facilement, sans connaissances préalables, sans diplôme en informatique, et sans avoir besoin de suivre des formations coûteuses. Que vous souhaitiez créer un site vitrine pour votre activité, un blog personnel, un petit site associatif ou simplement comprendre comment fonctionne le web, ce guide est fait pour vous.\r\n\r\nVous y apprendrez pas à pas :\r\n\r\nà créer une page web en HTML, la structurer correctement et y intégrer du texte, des images, des liens, des formulaires simples ;\r\n\r\nà mettre en forme vos pages avec CSS, choisir des couleurs, des polices, aligner vos contenus, créer une mise en page moderne et responsive (adaptée aux mobiles) ;\r\n\r\nà ajouter de l’interactivité avec JavaScript, afficher un message, modifier un élément au clic, valider un formulaire ;\r\n\r\nà découvrir PHP, le langage qui permet de générer des pages dynamiques, traiter des formulaires, afficher des contenus personnalisés ;\r\n\r\nà utiliser MySQL, le système de base de données le plus utilisé sur le web, pour enregistrer et afficher vos données en toute simplicité ;\r\n\r\nCe livre vous donne toutes les clés pour comprendre les bases du développement web et créer votre propre site internet sans aide extérieure. Il regroupe en un seul volume tout ce qu’on cherche souvent éparpillé sur des dizaines de tutos contradictoires.\r\n\r\nQue vous soyez étudiant, indépendant, curieux, salarié, artisan ou simplement motivé à apprendre, vous trouverez ici un livre pour apprendre à créer un site web complet, professionnel, et évolutif.\r\n\r\nCréer un site web ne devrait pas être réservé à ceux qui savent coder. Avec ce livre, c’est accessible à tous. Vous apprenez à votre rythme, en comprenant vraiment ce que vous faites, et vous construisez un projet concret, utile, que vous serez fier de montrer.\r\n\r\nHTML, CSS, JavaScript, PHP, MySQL : tout ce qu’il vous faut, dans un seul guide, clair, accessible et efficace.', 35.9, 'prod_699e9966d6e2f8.72011906.jpg'),
(25, 'Comment Devenir Développeur Web: Apprendre à coder, les formations pour atteindre rapidement le niveau de programmeur pro. Exemples en Javascript et ... meilleurs rémunérations salarié/freelance.', 'Plongez dans l&#039;univers captivant du développement web grâce à ce guide complet qui vous emmènera du débutant enthousiaste au professionnel accompli dans le monde numérique. Découvrez comment donner vie à vos idées, concevoir des sites web interactifs et apprendre les compétences cruciales pour une carrière passionnante dans ce domaine en plein essor. Si vous avez soif de créer, d&#039;innover et d&#039;explorer l’univers du web, ce livre vous ouvre les portes de l&#039;avenir.\r\n\r\nLoin d&#039;être une simple introduction à la programmation, ce guide éclairant vous prépare pour une carrière florissante dans le domaine. Vous y découvrirez comment construire un portfolio captivant, réussir des entretiens techniques et négocier un salaire compétitif en tant que professionnel du web. De plus, explorez le style de vie passionnant d&#039;un développeur web moderne, des opportunités de freelance à la flexibilité de travailler en voyageant.\r\n\r\nSi vous rêvez de créer, d&#039;innover et d&#039;embrasser un avenir numérique en constante évolution, &quot;Comment Devenir Développeur Web&quot; est votre allié incontournable. Abordez ce voyage avec confiance et excitation, et préparez-vous à bâtir un avenir exceptionnel dans l&#039;univers dynamique du développement web.\r\n\r\nCe que vous allez apprendre dans ce livre :\r\nDécouvrir le Monde du Développement Web : Comprenez en profondeur le rôle et les compétences nécessaires pour devenir un développeur web accompli.\r\nMaîtriser les Langages de Programmation : Explorez une variété de langages, de HTML et CSS à JavaScript, Python, C#, PHP et bien plus encore.\r\nNaviguer à Travers les Frameworks et Bibliothèques : Apprenez à utiliser des outils puissants tels que Vue.js, React, Express.js, Django, et bien d&#039;autres pour créer des applications web modernes.\r\nAcquérir des Compétences en Algorithmique et Structures de Données : Plongez dans les bases de la programmation avec des concepts tels que les variables, les boucles et les algorithmes.\r\nConcevoir des Sites Web Ergonomiques : Appréhendez les principes de l&#039;UI/UX design et du responsive design pour créer des sites web esthétiques et adaptés à tous les appareils.\r\nConstruire un Portfolio Convaincant : Découvrez comment créer un portfolio professionnel pour démontrer vos compétences et attirer l&#039;attention des employeurs.\r\nSe Préparer aux Entretiens Techniques : Recevez des conseils pratiques pour aborder avec confiance les entretiens techniques et réussir à démontrer vos connaissances.\r\nNégocier Votre Salaire et Évoluer dans Votre Carrière : Apprenez à négocier votre salaire de manière efficace et explorez les possibilités d&#039;évolution professionnelle en tant que développeur web.\r\nExplorer le Monde du Freelance et du Travail en Voyageant : Découvrez comment tirer parti de vos compétences pour travailler en freelance ou en tant que digital nomad tout en voyageant.\r\nSuivre les Tendances Salariales et les Perspectives d&#039;Évolution : Comprenez les facteurs qui influencent les salaires et anticipez les évolutions futures dans l&#039;industrie du développement web.\r\nIdentifier les Meilleures Ressources pour Apprendre : Accédez à une liste détaillée d&#039;écoles, de plateformes d&#039;e-learning, de tutoriels et de ressources communautaires pour renforcer vos compétences.\r\nCe livre vous emmène dans un voyage captivant à travers les fondements du développement web, des compétences techniques aux stratégies de carrière, pour vous préparer à exceller dans l&#039;univers numérique en constante évolution.', 14.99, 'prod_699e99d12b32b7.52645465.jpg'),
(26, '30 exercices HTML/ CSS avec corrigés: Perfectionnez vos compétences en création de sites internet', 'Ce cahier de 30 exercices HTML/CSS avec corrigés vous accompagnera lors de votre apprentissage du HTML et du CSS. Idéal pour des débutants qui souhaitent avoir des idées de petits projets pour s’entraîner, cet ouvrage vous propose de réaliser des exercices progressifs.\r\n\r\nCe livre couvre de nombreux sujets en HTML :\r\nLes balises sémantiques HTML5 (améliorez la structure de vos pages pour le référencement et l&amp;amp;#039;accessibilité).\r\nLes tableaux (concevez des tableaux complexes et apprenez à les mettre en forme efficacement).\r\nLes formulaires...\r\nAinsi qu&amp;amp;#039;en CSS :\r\nLes variables CSS.\r\nLes boîtes flexibles (flexbox), idéales pour réaliser des mises en page réactives.\r\nLes grilles CSS pour concevoir des mises en page avancées.\r\nLe responsive design, adaptez vos sites pour qu&amp;amp;#039;ils s&amp;amp;#039;affichent parfaitement sur tous les types d&amp;amp;#039;appareils.\r\nLes pseudo-éléments...\r\nEn accomplissant ces exercices, vous serez capable de mettre en pratique vos compétences afin de maîtriser le HTML/CSS et de faire de vos projets web des réussites visuelles et fonctionnelles.', 9.91, 'prod_699f10f311a317.87356444.jpg'),
(27, 'Mon pense-bête HTML/ CSS: L\'essentiel du HTML5 et CSS3 dans un mémento tout en couleur (Aide-mémoires HTML/CSS, Javascript et PHP)', 'Mon pense-bête HTML/CSS est un ouvrage destiné aux débutants qui souhaitent s’initier au\r\nlangage de base qu’est le HTML pour créer un site internet. Celui-ci viendra mettre du contenu\r\nau site web tandis que le CSS se chargera de la mise en page et de mettre du style aux\r\néléments HTML.\r\nCet aide-mémoire sur le HTML/CSS abordera de nombreuses notions avec des exemples.\r\nMais rien ne vous empêche de consulter les documentations officielles pour approfondir le\r\nsujet.\r\nCe pense-bête couvrira les sujets suivants :\r\nStructure d&amp;amp;amp;amp;amp;#039;une page HTML\r\nLes balises de base du HTML\r\nLes liens hypertextes\r\nLes tableaux\r\nLes formulaires\r\nMettre du style à une page HTML\r\nLes boîtes et le positionnement\r\nLe responsive design\r\nFlexbox\r\nModèle des grilles', 11.9, 'prod_69a00f7c2e1996.54691865.jpg'),
(28, 'Créer un site Web pour les Nuls, 12è édition : Livre d\'informatique, Se lancer dans la création de site Internet, Apprendre à créer un site complet avec Wordpress et les bases du HTML', 'GUIDE POUR WEBMASTER DEBUTANT:\r\n\r\nVous voulez afficher vos talents, mettre en avant les produits de votre entreprise ou bien vous êtes Webmaster débutant ? Alors, bienvenue au club !\r\n\r\nDu surfer débutant à l\'internaute confirmé, ce livre d\'informatique pour les Nuls vous dit tout ce que vous devez savoir pour créer votre propre site Internet, du simple serveur FTP à l\'intérieur de votre bureau jusqu\'à la mise en service de serveurs Web virtuels accessibles du monde entier. Vous apprendrez également à créer un site avec les deux outils de développement les plus utilisés, Dreamweaver et HTML.\r\n\r\nAu programme :\r\nConstruire son site en fonction de sa cible\r\nOrganisation du contenu et des éléments de navigation\r\nTests utilisateurs\r\nHTML, la pierre angulaire du Web\r\nCréer des images pour le Web\r\nPositionnement précis avec les calques CSS\r\nIntégration de technologies avancées\r\nRevue de détail des ressources nécessaires en matériel et en logiciel\r\nCréer un site complet avec WordPress\r\n\r\nPOUR TOUS NIVEAUX:\r\n\r\nCe livre d\'informatique pour les Nuls s\'adresse à ceux qui souhaitent apprendre la création de site Internet.\r\nQue vous soyez débutant en informatique ou que vous possédiez quelques notions, cet ouvrage vous donnera les clés. Des bases du HTML au CSS, en passant par l\'utilisation de l\'outil de création Wordpress, vous aurez toutes les cartes en main pour vous lancer.\r\n\r\nCRÉEZ VOTRE PREMIER SITE:\r\n\r\nQue vous souhaitiez mettre en avant votre entreprise ou simplement vous entraîner à la création de site internet, ce livre d\'informatique pour les Nuls est fait pour vous. Vous découvrirez HTML, apprendrez à créer un site complet avec Wordpress et à l\'animer.\r\n\r\nGrâce à notre livre d\'informatique, vous pourrez créer votre propre site et apprendre à le gérer, de la création à son organisation. En résumé, vous deviendrez un vrai pro de la création de site Internet !', 24.95, 'prod_69a0368b06f583.27358833.jpg'),
(32, 'HTML et CSS Facile pour les Non-Programmeurs : Un guide pratique du développement web pour les débutants: De zéro à héros du web : simplifier le HTML et le', 'Ce livre offre un accès gratuit à notre plateforme d\'apprentissage en ligne, qui comprend :\r\n\r\n✅ Dépôt de code gratuit avec tous les blocs de code utilisés dans ce livre\r\n\r\n✅ Accès aux chapitres gratuits de toute notre bibliothèque de livres de programmation publiés\r\n\r\n✅ Support client premium gratuit\r\n\r\n✅ Et bien plus encore...\r\n\r\nDécouvrez le Pouvoir du Développement Web\r\n\r\nÀ une époque où la toile numérique devient de plus en plus essentielle, le pouvoir de créer votre propre espace sur Internet n\'a jamais été aussi précieux. Que vous cherchiez à présenter votre portfolio, lancer votre entreprise en ligne ou simplement partager votre voix avec le monde, comprendre les langages fondamentaux du web, HTML et CSS, est la première étape pour laisser votre empreinte. Mais, par où commencer si vous n\'avez jamais codé auparavant ? « HTML et CSS pour les Non-Programmeurs : Des Fondamentaux au Lancement » est là pour éclairer votre chemin.\r\n\r\nEntreprendre un Voyage d\'Apprentissage\r\n\r\nImaginez pouvoir créer votre propre site web sans vous empêtrer dans le jargon technique complexe ou vous sentir submergé par les concepts apparemment complexes de la programmation. Cet objectif n\'est pas aussi inaccessible qu\'il n\'y paraît, grâce à ce livre méticuleusement conçu. Il est spécifiquement destiné aux débutants comme vous, et vise à transformer la tâche difficile du développement web en un voyage gérable, agréable et même passionnant.\r\n\r\nCe livre vous prend par la main et vous guide depuis le début, où vous comprendrez la structure sous-jacente d\'Internet. Ensuite, il vous accompagne à chaque étape du chemin, tandis que vous naviguez dans le monde du codage et du développement web. Chaque chapitre de ce livre est soigneusement conçu pour démystifier les mystères du développement web. Il le fait avec un niveau de clarté et de simplicité facile à comprendre, sans vous submerger avec trop d\'informations d\'un seul coup.\r\n\r\nDe plus, ce livre garantit que l\'apprentissage du développement web n\'a pas à être une corvée ennuyeuse. Chaque leçon intègre une touche de plaisir, rendant le processus d\'apprentissage non seulement éclairant, mais aussi divertissant. Au moment où vous arriverez à la dernière page, non seulement vous aurez appris le développement web, mais vous aurez lancé votre propre site web entièrement fonctionnel.\r\n\r\nTransformez vos Idées en Réalité\r\n\r\nApprentissage Intégral : Plongez dans les éléments fondamentaux de HTML et CSS, en commençant par les bases et en progressant vers des techniques plus complexes, le tout expliqué dans un langage que vous comprenez.\r\nProjets Pratiques : Donnez vie à votre apprentissage avec des projets du monde réel. À la fin du livre, vous aurez construit un portfolio en ligne et une page de destination pour un produit numérique, prêt à impressionner le monde.\r\nMeilleures Pratiques et Principes : Apprenez non seulement à coder, mais à créer des sites web magnifiques, réactifs et faciles à utiliser, en appliquant des principes de conception modernes et les meilleures pratiques.\r\nLancez votre Site Web : Découvrez les secrets de l\'hébergement web, des noms de domaine, du référencement et plus encore. Allez au-delà de la création de votre site : apprenez à le lancer avec succès et à le rendre visible pour votre public.\r\n\r\nFaites le Premier Pas Aujourd\'hui\r\n\r\n« HTML et CSS Facile pour les Non-Programmeurs » est plus qu\'un livre ; c\'est votre premier pas vers la maîtrise du monde numérique. Que vous rêviez de lancer un blog personnel, créer une boutique en ligne ou simplement acquérir une nouvelle compétence de plus en plus vitale à notre ère numérique, ce livre est la clé pour débloquer ces possibilités.', 47.88, 'prod_69a036efadcbb7.16305715.jpg'),
(33, 'Métier Développeur: Comprendre, choisir et évoluer dans le développement web et jeux vidéo', '????Vous rêvez de devenir développeur mais ne savez pas par où commencer ?\r\n\r\nCe guide est fait pour vous. Que vous soyez débutant complet, étudiant, en reconversion professionnelle ou simplement curieux de comprendre ce métier d\'avenir, vous découvrirez tout ce qu\'il faut savoir pour vous lancer avec confiance.\r\n\r\n???? Ce que vous allez découvrir :\r\n\r\nLes fondamentaux du métier\r\n\r\nPourquoi devenir développeur aujourd\'hui (opportunités, salaires, flexibilité)\r\nLes missions concrètes et le quotidien réel d\'un développeur\r\nLes compétences techniques et humaines indispensables\r\nToutes les spécialités décryptées\r\n\r\nFront-end, back-end, full-stack : comprendre les différences\r\nDéveloppement mobile, jeux vidéo, UI/UX, sécurité…\r\nÉtudes de cas réelles avec exemples de projets concrets\r\nVotre plan d\'action pour démarrer\r\n\r\nLes différentes voies d\'accès : université, bootcamp, autodidacte, reconversion\r\nComment construire votre portfolio pour impressionner les recruteurs\r\nDécrocher votre premier poste : CV, entretiens techniques, négociation\r\nLes clés pour évoluer\r\n\r\nSe former continuellement et rester à jour\r\nChoisir entre salariat, freelance ou entrepreneuriat\r\nRessources essentielles et communautés actives\r\n???? Les + de ce guide :\r\n\r\nDes explications claires, sans jargon inutile\r\nDes illustrations et schémas pour visualiser les concepts\r\nUn glossaire complet de plus de 150 termes techniques\r\nDes exemples de projets étape par étape\r\nDes conseils pratiques de professionnels en exercice\r\n????À propos de l\'auteure\r\nAntonella De Chiara est développeuse web et jeux vidéo, formatrice et fondatrice d\'Itamde. Fort d\'une expérience terrain et pédagogique, elle accompagne depuis des années les débutants dans leur apprentissage de la programmation.\r\n\r\nCe livre vous donne une vision complète et réaliste du métier, sans vous noyer dans la technique. C\'est le point de départ idéal pour quiconque souhaite comprendre le développement et s\'y lancer avec les bonnes bases.', 14.76, 'prod_69a03788300df7.01589211.jpg'),
(34, 'Apprendre le développement web au lycée avec les langages HTML5, CSS3, JavaScript, PHP et MySQL, ICN-ISN', 'Vous rêvez de devenir développeur mais ne savez pas par où commencer ?\r\n\r\nCe guide est fait pour vous. Que vous soyez débutant complet, étudiant, en reconversion professionnelle ou simplement curieux de comprendre ce métier d\'avenir, vous découvrirez tout ce qu\'il faut savoir pour vous lancer avec confiance.\r\n\r\n???? Ce que vous allez découvrir :\r\n\r\nLes fondamentaux du métier\r\n\r\nPourquoi devenir développeur aujourd\'hui (opportunités, salaires, flexibilité)\r\nLes missions concrètes et le quotidien réel d\'un développeur\r\nLes compétences techniques et humaines indispensables\r\nToutes les spécialités décryptées\r\n\r\nFront-end, back-end, full-stack : comprendre les différences\r\nDéveloppement mobile, jeux vidéo, UI/UX, sécurité…\r\nÉtudes de cas réelles avec exemples de projets concrets\r\nVotre plan d\'action pour démarrer\r\n\r\nLes différentes voies d\'accès : université, bootcamp, autodidacte, reconversion\r\nComment construire votre portfolio pour impressionner les recruteurs\r\nDécrocher votre premier poste : CV, entretiens techniques, négociation\r\nLes clés pour évoluer\r\n\r\nSe former continuellement et rester à jour\r\nChoisir entre salariat, freelance ou entrepreneuriat\r\nRessources essentielles et communautés actives\r\n???? Les + de ce guide :\r\n\r\nDes explications claires, sans jargon inutile\r\nDes illustrations et schémas pour visualiser les concepts\r\nUn glossaire complet de plus de 150 termes techniques\r\nDes exemples de projets étape par étape\r\nDes conseils pratiques de professionnels en exercice\r\n???? À propos de l\'auteure\r\nAntonella De Chiara est développeuse web et jeux vidéo, formatrice et fondatrice d\'Itamde. Fort d\'une expérience terrain et pédagogique, elle accompagne depuis des années les débutants dans leur apprentissage de la programmation.\r\n\r\nCe livre vous donne une vision complète et réaliste du métier, sans vous noyer dans la technique. C\'est le point de départ idéal pour quiconque souhaite comprendre le développement et s\'y lancer avec les bonnes bases.', 14.76, 'prod_69a168c3141126.47415472.jpg'),
(35, 'Programmation Web pour les Nuls (Informatique pour les nuls) Kindle Edition', 'Un livre indispensable pour débuter dans le développement d\'applications pour le Web\r\nCe livre va vous donner les bases nécessaire au développement de site Web modernes. Vous découvrirez les différents langages du Web et la manière d\'optimiser leur utilisation dans le développement de vos applications.\r\n\r\n\r\nAu programme :\r\nLes bases du HTML\r\nUtiliser les styles avec les CSS\r\nUtiliser Flexbox pour organier ses pages\r\nEcrire des programmes en JavaScript\r\nMettre en oeuvre Ajax et JSON', 19.99, 'prod_69a1691f47fd22.18817847.jpg');

